fn frame(t: i32) {
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(0);
    if down == 1 && prev == 0 {
        host::audio::tone_at(262, 140, 0, 0);
        host::audio::tone_at(330, 140, 0, 150);
        host::audio::tone_at(392, 140, 0, 300);
        host::audio::tone_at(523, 200, 0, 450);
    }
    host::display::state_set(0, down);
    host::display::clear(0x101010);
    host::display::draw_string(8, 10, "TAP = ARPEGGIO", 0xffffff, 2);
    let notes = [262, 330, 392, 523];
    let mut i: i32 = 0;
    while i < 4 {
        host::display::fill_rect(20 + i * 40, 200 - notes[i] / 4, 30, notes[i] / 4, 0x00aaff);
        i = i + 1;
    }
    host::display::present();
}
